  "schema_version": 1,
  "id": "baseline-review-simulated",
  "title": "Table 1. Baseline characteristics — SIMULATED EXAMPLE / 模拟示例",
  "simulated": true,
  "columns": [
    {
      "id": "a",
      "label": "Treatment A (N=100)",
      "align": "right"
    },
    {
      "id": "b",
      "label": "Treatment B (N=120)",
      "align": "right"
    }
  ],
  "headers": [
    {
      "id": "ha",
      "label": "Treatment A (N=100)",
      "column_id": "a"
    },
    {
      "id": "hb",
      "label": "Treatment B (N=120)",
      "column_id": "b"
    }
  ],
  "rows": [
    {
      "id": "age",
      "label": "Age (years)",
      "cells": {
        "a": "61.2 (10.4)",
        "b": "60.8 (11.1)"
      }
    },
    {
      "id": "female",
      "label": "Female sex",
      "cells": {
        "a": "54 (54.5%)",
        "b": "62 (52.5%)"
      }
    },
    {
      "id": "bmi",
      "label": "BMI (kg/m²)",
      "cells": {
        "a": "27.1 (4.2)",
        "b": "26.8 (4.0)"
      }
    }
  ],
  "footnotes": [
    {
      "id": "simulation",
      "text": "SIMULATED EXAMPLE / 模拟示例：所有数值均为展示而虚构，不是研究发现，不能直接用于投稿。"
    },
    {
      "id": "summary",
      "text": "Values are mean (SD) for continuous variables and n (%) for Female sex; mean, SD and percentages use one decimal place. Column N is the full group size; missing values are excluded separately for each variable."
    },
    {
      "id": "missing",
      "text": "Missing counts, Treatment A / Treatment B: Age 2 / 3; Female sex 1 / 2; BMI 5 / 8. Female-sex percentages use nonmissing denominators 99 / 118."
    }
  ]
}
